WFJ.Data.add("book", {
  ["620f08e355174b74"] = { "Saluti a te, fratello o sorella. Gli spiriti dicono che per te è arrivato il momento di aiutare i nostri alleati. Tu hai legami forti con gli elementi, e tu hai molto più potere di quando hai cominciato le tue lezioni con me.\n\nOra io ti mando da Shikrik, l'orchessa che istruisce gli sciamani nella ⟦Valley of Trials=Valle delle Sfide⟧. Lei sa già che tu vai a studiare con lei. Rendi fieri i nostri antenati. Finché non ci rivediamo, che la fiamma ti tenga al caldo e il vento ti stia alle spalle.\n\n-Ishi-yo", "." },
  ["6278be579f9443fd"] = { "Kel'Thuzad scese nelle profondità della terra gelida e trovò la strada fino al fondo del ghiacciaio. Lì, nell'interminabile caverna di ghiaccio e di ombre, si prostrò davanti al Trono di Ghiaccio e offrì la sua anima all'oscuro signore dei morti.", "." },
  ["627f1236bb620cdf"] = { "Spero che questo sigillo ti trovi in buona salute, {name}. Gli spiriti mi hanno parlato del tuo arrivo e ho mandato subito un messaggio. Non vedo l'ora di condividere con te le mie esperienze e di aiutarti a orientarti mentre ti prepari a lasciare Teldrassil per questioni più importanti.\n\nCon tutto quello che è successo negli ultimi anni, possiamo fare molto per aiutare le altre razze di Azeroth. Quando te la senti, cercami dentro Aldrassil, al secondo livello.\n\n-Shanda, istruttrice dei sacerdoti", "." },
  ["62c7508f9a3be141"] = { "Questa tassa, insieme alle crescenti tensioni politiche per le dispute di confine, generò un malcontento diffuso. Sembrava che il fragile patto che aveva unito le nazioni umane nell'ora più buia potesse spezzarsi da un momento all'altro.", "." },
